class Resource extends Vector {
 heading='A map of invisible currents.';note='Streamlines follow a field, finding their own way through it.';
 build(){const random=seedRandom(this.number('seed',35,1,100)),count=this.number('detail',45,18,80);const centers=Array.from({length:5},()=>({x:random()*720,y:random()*420,spin:random()>.5?1:-1}));let paths='';for(let i=0;i<count;i++){let x=25+random()*670,y=20+random()*380,d=`M${x.toFixed(1)} ${y.toFixed(1)}`;for(let step=0;step<115;step++){let vx=.3,vy=.05;for(const p of centers){const dx=x-p.x,dy=y-p.y,r=Math.max(900,dx*dx+dy*dy);vx+=-dy/r*120*p.spin;vy+=dx/r*120*p.spin;}const length=Math.hypot(vx,vy)||1;x+=vx/length*3;y+=vy/length*3;if(x<18||x>702||y<18||y>402)break;d+=`L${x.toFixed(1)} ${y.toFixed(1)}`;}paths+=`<path d="${d}" fill="none" stroke="${i%4===0?'#c9a97b':this.color}" stroke-width="${i%7===0?1.8:.7}" opacity="${.15+random()*.6}"/>`;}
 return this.svg(`<defs><clipPath id="${this.artId}-clip"><rect x="18" y="18" width="684" height="384" rx="180"/></clipPath></defs><rect x="18" y="18" width="684" height="384" rx="180" fill="#142a28"/><g clip-path="url(#${this.artId}-clip)">${paths}</g>${centers.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3" fill="#d8cfb2" opacity=".7"/>`).join('')}<text x="360" y="411" text-anchor="middle" fill="#899f91" font-family="monospace" font-size="8" letter-spacing="2">A FIELD WITHOUT BORDERS / SEED ${this.number('seed',35)}</text>`);}
}
